  "milestones": [
    {
      "id": "find_orange_banner",
      "description": "The player has found the orange banner by navigating close to it inside the oak plank shelter.",
      "task_type": "find",
      "target_item": "orange_banner",
      "rules": [
        {
          "rule_type": "position_inside_box",
          "description": "Player is inside or at the entrance of the oak plank shelter, close enough to the orange wall banner to have found it.",
          "parameters": {
            "x_min": "~4",
            "x_max": "~10",
            "y_min": "~-1",
